# Not run here: needs an NVIDIA GPU with flash-attn installed.
import torch, torch.nn.functional as F
from flash_attn import flash_attn_func  # FA3: flash_attn_interface, FA4: flash_attn.cute

def time_ms(fn, iters=100, warmup=10):
    for _ in range(warmup):
        fn()
    start = torch.cuda.Event(enable_timing=True)
    end = torch.cuda.Event(enable_timing=True)
    torch.cuda.synchronize()
    start.record()
    for _ in range(iters):
        fn()
    end.record()
    torch.cuda.synchronize()
    return start.elapsed_time(end) / iters       # milliseconds per call

B, H, d = 4, 16, 128
for N in (1024, 2048, 4096, 8192, 16384):
    q, k, v = (torch.randn(B, N, H, d, device="cuda", dtype=torch.bfloat16)
               for _ in range(3))
    qt, kt, vt = (x.transpose(1, 2) for x in (q, k, v))  # SDPA: (B, H, N, d)
    for causal in (False, True):
        flops = 4 * B * H * N * N * d / (2 if causal else 1)
        fa = time_ms(lambda: flash_attn_func(q, k, v, causal=causal))
        sd = time_ms(lambda: F.scaled_dot_product_attention(
            qt, kt, vt, is_causal=causal))
        tflops = [flops / (t * 1e-3) / 1e12 for t in (fa, sd)]
        print(N, causal, [f"{x:.0f} TFLOPs/s" for x in tflops])
